SELECT a.OBJ_NM    AS objNm,
       a.ATTR_NM   AS attrNm
  FROM TB_DATA_MODEL_ATTR a
 WHERE a.DM_ID    = #{dmId}
   AND a.DOMAIN_ID = #{domainId}
   AND a.USE_YN   = 'Y'
